import 'package:flutter/material.dart';

import 'studio_generated.dart';

void main() {
  // Where pages' imported data comes from: the tenant API, and the website
  // (whose server holds any key an import is sent with).
  studioApiUrl = "";
  studioSiteUrl = "";
  // Route tokens (Route.cart …) open this project's own page paths.
  studioRoutePaths.addAll(const {
    "location": "/select-location",
    "stores": "/select-store",
    "menu": "/stores/\$storeId",
    "product": "/stores/\$storeId/products/\$productId",
    "cart": "/stores/\$storeId/cart",
    "checkout": "/stores/\$storeId/checkout",
    "orders": "/orders",
    "tracking": "/orders/\$orderId",
    "account": "/account",
    "addresses": "/addresses",
    "reset-password": "/reset-password",
  });
  runApp(const StudioApp());
}

class StudioApp extends StatelessWidget {
  const StudioApp({super.key});

  @override
  Widget build(BuildContext context) {
    return ValueListenableBuilder<ThemeMode?>(
      // ToggleDarkMode: the mode it switched to, over Config's.
      valueListenable: studioThemeMode,
      builder: (context, mode, _) => MaterialApp(
      title: "Storefront app",
      debugShowCheckedModeBanner: false,
      // The Studio preview's palette, with this project's Config colours.
      theme: studioTheme(const {

      }),
      // The dark palette, used when the app is dark.
      darkTheme: studioTheme(const {

      }, brightness: Brightness.dark),
      themeMode: mode ?? ThemeMode.light,
      // The storefront (location, stores, menu, cart) above every page.
      builder: (context, child) => StudioStorefrontScope(child: child!),
      initialRoute: "/select-location",
      // Only the first page: not the pages its path is nested under.
      onGenerateInitialRoutes: (initial) => [_route(RouteSettings(name: initial))],
      onGenerateRoute: _route,
      navigatorObservers: [_shown],
    ),
    );
  }
}

/// Each page's app bar and bottom navigation components.
const _bars = <String, List<String>>{
  "location": ["SharedHeader", ""],
  "stores": ["SharedHeader", ""],
  "menu": ["SharedHeader", "StoreTabs"],
  "product": ["SharedHeader", ""],
  "cart": ["SharedHeader", "StoreTabs"],
  "checkout": ["SharedHeader", ""],
  "orders": ["SharedHeader", "StoreTabs"],
  "tracking": ["SharedHeader", ""],
  "account": ["SharedHeader", "StoreTabs"],
  "addresses": ["SharedHeader", ""],
  "reset-password": ["SharedHeader", ""],
};

/// Whether two pages share their app bar or bottom navigation.
bool _sharesBar(String? from, String? to) {
  final a = _bars[from], b = _bars[to];
  if (a == null || b == null) return false;
  return (a[0].isNotEmpty && a[0] == b[0]) || (a[1].isNotEmpty && a[1] == b[1]);
}

/// The page on screen, as the navigator changes it.
class _ShownPage extends NavigatorObserver {
  String? pageId;
  @override
  void didPush(Route<dynamic> route, Route<dynamic>? previousRoute) =>
      pageId = _pageIdOf(route.settings.name);
  @override
  void didPop(Route<dynamic> route, Route<dynamic>? previousRoute) =>
      pageId = _pageIdOf(previousRoute?.settings.name);
  @override
  void didReplace({Route<dynamic>? newRoute, Route<dynamic>? oldRoute}) =>
      pageId = _pageIdOf(newRoute?.settings.name);
}

final _shown = _ShownPage();

/// A page's route: without a transition from a page sharing its app bar or
/// bottom navigation (the bar stays still), and with the platform's own
/// otherwise.
Route<dynamic> _route(RouteSettings settings) {
  Widget build(BuildContext context) => _page(
        settings.name ?? "/select-location",
        settings.arguments is Map<String, dynamic>
            ? settings.arguments as Map<String, dynamic>
            : const {},
      );
  if (_sharesBar(_shown.pageId, _pageIdOf(settings.name))) {
    return PageRouteBuilder<void>(
      settings: settings,
      transitionDuration: Duration.zero,
      reverseTransitionDuration: Duration.zero,
      pageBuilder: (context, animation, secondaryAnimation) => build(context),
    );
  }
  return MaterialPageRoute<void>(settings: settings, builder: build);
}

String? _pageIdOf(String? location) {
  if (location == null) return null;
  final segments = Uri.parse(location).pathSegments;
  for (final MapEntry(key: pattern, value: pageId) in _patterns.entries) {
    if (_match(pattern, segments) != null) return pageId;
  }
  return null;
}

/// Each page's path pattern. A `$name` segment matches any value and is
/// passed to the page as `route.params.name`.
const _patterns = <String, String>{
  "/select-location": "location",
  "/select-store": "stores",
  "/stores/\$storeId": "menu",
  "/stores/\$storeId/products/\$productId": "product",
  "/stores/\$storeId/cart": "cart",
  "/stores/\$storeId/checkout": "checkout",
  "/orders": "orders",
  "/orders/\$orderId": "tracking",
  "/account": "account",
  "/addresses": "addresses",
  "/reset-password": "reset-password",
};

/// Pages without their own Scaffold get the preview's 16px content padding
/// and scroll.
const _padded = <String>{};

Widget _build(String pageId) {
  switch (pageId) {
    case "location":
      return const StudioPageData(page: "location", imports: [StudioImport(name: "cities", path: "/cities", select: "data"), StudioImport(name: "location", client: "location")], child: StudioPage1Location());
    case "stores":
      return const StudioPageData(page: "stores", imports: [StudioImport(name: "location", client: "location"), StudioImport(name: "stores", client: "stores")], child: StudioPage2Stores());
    case "menu":
      return const StudioPageData(page: "menu", imports: [StudioImport(name: "menu", path: "/stores/{store}/menu", params: [StudioImportParam("store", "route", "storeId")]), StudioImport(name: "store", client: "store"), StudioImport(name: "products", path: "/stores/{store}/products", query: ["category_id", "limit"], select: "data", params: [StudioImportParam("store", "import", "store.id")])], child: StudioPage3Menu());
    case "product":
      return const StudioPageData(page: "product", imports: [StudioImport(name: "product", path: "/products/{id}", params: [StudioImportParam("id", "route", "productId")]), StudioImport(name: "store", path: "/stores/{store}", params: [StudioImportParam("store", "route", "storeId")]), StudioImport(name: "choices", client: "choices")], child: StudioPage4Product());
    case "cart":
      return const StudioPageData(page: "cart", imports: [StudioImport(name: "store", path: "/stores/{store}", params: [StudioImportParam("store", "route", "storeId")]), StudioImport(name: "cart", client: "cart")], child: StudioPage5Cart());
    case "checkout":
      return const StudioPageData(page: "checkout", imports: [StudioImport(name: "store", path: "/stores/{store}", params: [StudioImportParam("store", "route", "storeId")]), StudioImport(name: "cart", client: "cart"), StudioImport(name: "checkout", client: "checkout"), StudioImport(name: "location", client: "location"), StudioImport(name: "deliveryOptions", path: "/stores/{store}/delivery-options", params: [StudioImportParam("store", "import", "store.id")])], child: StudioPage6Checkout());
    case "orders":
      return const StudioPageData(page: "orders", imports: [StudioImport(name: "orders", path: "/orders", query: ["limit"], select: "data", auth: true)], child: StudioPage7Orders());
    case "tracking":
      return const StudioPageData(page: "tracking", imports: [StudioImport(name: "order", path: "/orders/{id}", auth: true, params: [StudioImportParam("id", "route", "orderId")]), StudioImport(name: "review", client: "review")], child: StudioPage8Tracking());
    case "account":
      return const StudioPageData(page: "account", imports: [StudioImport(name: "me", path: "/me", auth: true)], child: StudioPage9Account());
    case "addresses":
      return const StudioPageData(page: "addresses", imports: [StudioImport(name: "addresses", path: "/addresses", select: "data", auth: true)], child: StudioPage10Addresses());
    case "reset-password":
      return const StudioPage11ResetPassword();
    default:
      return const StudioPage1Location();
  }
}

/// Finds the page for [location] and hands it the route it was opened with.
Widget _page(String location, Map<String, dynamic> values) {
  final uri = Uri.parse(location);
  for (final MapEntry(key: pattern, value: pageId) in _patterns.entries) {
    final params = _match(pattern, uri.pathSegments);
    if (params == null) continue;
    return _scoped(pageId, pattern, uri.path, params, values);
  }
  return _scoped("location", "/select-location", uri.path, const {}, values);
}

Map<String, String>? _match(String pattern, List<String> segments) {
  final parts = pattern.split('/').where((part) => part.isNotEmpty).toList();
  if (parts.length != segments.length) return null;
  final params = <String, String>{};
  for (var index = 0; index < parts.length; index++) {
    if (parts[index].startsWith(r'$')) {
      params[parts[index].substring(1)] = segments[index];
    } else if (parts[index] != segments[index]) {
      return null;
    }
  }
  return params;
}

Widget _scoped(
  String pageId,
  String pattern,
  String path,
  Map<String, String> params,
  Map<String, dynamic> values,
) {
  return StudioScope(
    values: {
      // What the navigation carried, e.g. the product OpenProduct opened.
      ...values,
      'route': {
        'pageId': pageId,
        'pattern': pattern,
        'path': path,
        'params': params,
      },
    },
    child: Scaffold(
      body: SafeArea(
        // Like the preview, a page without its own Scaffold scrolls as a whole.
        child: _padded.contains(pageId)
            ? SingleChildScrollView(padding: const EdgeInsets.all(16), child: _build(pageId))
            : _build(pageId),
      ),
    ),
  );
}

